/* QKX_CAMERA_CUSTODY_WORKQ_BEGIN */
#ifdef CONFIG_QKX_OWNER_GATE
/* Only explicitly claimed CRM queues use these private task-pool leases. */
struct qkx_workq_custody {
	struct list_head entry;
	struct cam_req_mgr_core_workq *workq;
	unsigned char *state;
	unsigned int held, dispatch, external;
	bool closing, retiring;
	int error;
	void (*idle)(void *);
	void *target;
};
static LIST_HEAD(qkx_workq_owners);
static DEFINE_SPINLOCK(qkx_workq_lock);

static struct qkx_workq_custody *qkx_workq_find(
	struct cam_req_mgr_core_workq *workq)
{
	struct qkx_workq_custody *owner;

	list_for_each_entry(owner, &qkx_workq_owners, entry)
		if (owner->workq == workq)
			return owner;
	return NULL;
}

static int qkx_workq_index(struct qkx_workq_custody *owner,
	struct crm_workq_task *task)
{
	size_t offset = (size_t)task -
		(size_t)owner->workq->task.pool;

	if (offset % sizeof(*task) ||
		offset / sizeof(*task) >= owner->workq->task.num_task)
		return -EUCLEAN;
	return offset / sizeof(*task);
}

static bool qkx_workq_idle(struct qkx_workq_custody *owner)
{
	return owner->closing && !owner->held && !owner->dispatch &&
		!owner->external && !owner->error;
}

static void qkx_workq_return_locked(struct qkx_workq_custody *owner,
	struct crm_workq_task *task, int index)
{
	struct cam_req_mgr_core_workq *workq = owner->workq;

	spin_lock(&workq->lock_bh);
	list_del_init(&task->entry);
	task->cancel = 0;
	task->process_cb = NULL;
	task->priv = NULL;
	list_add_tail(&task->entry, &workq->task.empty_head);
	atomic_add(1, &workq->task.free_cnt);
	spin_unlock(&workq->lock_bh);
	owner->state[index] = 0;
	owner->held--;
}

static bool qkx_workq_get(struct cam_req_mgr_core_workq *workq,
	struct crm_workq_task **task)
{
	struct qkx_workq_custody *owner;
	unsigned long flags;
	int index;

	spin_lock_irqsave(&qkx_workq_lock, flags);
	owner = qkx_workq_find(workq);
	if (!owner) {
		spin_unlock_irqrestore(&qkx_workq_lock, flags);
		return false;
	}
	*task = NULL;
	if (!owner->closing && !owner->retiring && !owner->error) {
		spin_lock(&workq->lock_bh);
		if (!list_empty(&workq->task.empty_head)) {
			*task = list_first_entry(&workq->task.empty_head,
				struct crm_workq_task, entry);
			index = qkx_workq_index(owner, *task);
			if (index < 0 || owner->state[index]) {
				owner->error = -EUCLEAN;
				*task = NULL;
			} else {
				list_del_init(&(*task)->entry);
				atomic_sub(1, &workq->task.free_cnt);
				(*task)->ret = 0;
				owner->state[index] = 1; /* borrowed */
				owner->held++;
			}
		}
		spin_unlock(&workq->lock_bh);
	}
	spin_unlock_irqrestore(&qkx_workq_lock, flags);
	return true;
}

static bool qkx_workq_put(struct crm_workq_task *task)
{
	struct qkx_workq_custody *owner;
	void (*idle)(void *) = NULL;
	void *target = NULL;
	unsigned long flags;
	int index;

	spin_lock_irqsave(&qkx_workq_lock, flags);
	owner = qkx_workq_find(task->parent);
	if (!owner) {
		spin_unlock_irqrestore(&qkx_workq_lock, flags);
		return false;
	}
	index = qkx_workq_index(owner, task);
	if (index < 0 || (owner->state[index] != 1 &&
		owner->state[index] != 3) || !owner->held) {
		owner->error = -EUCLEAN;
	} else {
		qkx_workq_return_locked(owner, task, index);
		if (qkx_workq_idle(owner)) {
			idle = owner->idle;
			target = owner->target;
		}
	}
	spin_unlock_irqrestore(&qkx_workq_lock, flags);
	if (idle)
		idle(target);
	return true;
}

static bool qkx_workq_enqueue(struct crm_workq_task *task,
	void *priv, int32_t prio, int *result)
{
	struct qkx_workq_custody *owner;
	struct cam_req_mgr_core_workq *workq = task->parent;
	void (*idle)(void *) = NULL;
	void *target = NULL;
	unsigned long flags;
	int index;

	spin_lock_irqsave(&qkx_workq_lock, flags);
	owner = qkx_workq_find(workq);
	if (!owner) {
		spin_unlock_irqrestore(&qkx_workq_lock, flags);
		return false;
	}
	index = qkx_workq_index(owner, task);
	if (index < 0 || owner->state[index] != 1 || !owner->held) {
		owner->error = -EUCLEAN;
		*result = owner->error;
	} else if (task->cancel || owner->closing || !workq->job ||
		owner->error) {
		*result = owner->error ? owner->error :
			(owner->closing ? -ESHUTDOWN : (!workq->job ? -EINVAL : 0));
		qkx_workq_return_locked(owner, task, index);
		if (qkx_workq_idle(owner)) {
			idle = owner->idle;
			target = owner->target;
		}
	} else {
		task->priv = priv;
		task->priority = prio >= CRM_TASK_PRIORITY_0 &&
			prio < CRM_TASK_PRIORITY_MAX ? prio : CRM_TASK_PRIORITY_0;
		owner->state[index] = 2; /* queued: same retained ticket */
		spin_lock(&workq->lock_bh);
		list_add_tail(&task->entry,
			&workq->task.process_head[task->priority]);
		atomic_add(1, &workq->task.pending_cnt);
		queue_work(workq->job, &workq->work);
		spin_unlock(&workq->lock_bh);
		*result = 0;
	}
	spin_unlock_irqrestore(&qkx_workq_lock, flags);
	if (idle)
		idle(target);
	return true;
}

static int qkx_workq_run(struct crm_workq_task *task)
{
	struct qkx_workq_custody *owner;
	unsigned long flags;
	int index, result = 0;

	spin_lock_irqsave(&qkx_workq_lock, flags);
	owner = qkx_workq_find(task->parent);
	if (owner) {
		index = qkx_workq_index(owner, task);
		if (index < 0 || owner->state[index] != 2) {
			owner->error = -EUCLEAN;
			result = -EUCLEAN;
		} else {
			owner->state[index] = 3; /* running until callback returns */
			result = 1;
		}
	}
	spin_unlock_irqrestore(&qkx_workq_lock, flags);
	return result;
}

static void qkx_workq_dispatch(struct cam_req_mgr_core_workq *workq,
	bool enter)
{
	struct qkx_workq_custody *owner;
	void (*idle)(void *) = NULL;
	void *target = NULL;
	unsigned long flags;

	spin_lock_irqsave(&qkx_workq_lock, flags);
	owner = qkx_workq_find(workq);
	if (owner) {
		if (enter)
			owner->dispatch++;
		else if (!owner->dispatch)
			owner->error = -EUCLEAN;
		else
			owner->dispatch--;
		if (qkx_workq_idle(owner)) {
			idle = owner->idle;
			target = owner->target;
		}
	}
	spin_unlock_irqrestore(&qkx_workq_lock, flags);
	if (idle)
		idle(target);
}

static bool qkx_workq_destroy_begin(struct cam_req_mgr_core_workq *workq)
{
	struct qkx_workq_custody *owner;
	unsigned long flags;
	bool ready = true;

	spin_lock_irqsave(&qkx_workq_lock, flags);
	owner = qkx_workq_find(workq);
	if (owner) {
		owner->closing = true;
		ready = qkx_workq_idle(owner) && !owner->retiring;
		if (ready)
			owner->retiring = true;
	}
	spin_unlock_irqrestore(&qkx_workq_lock, flags);
	return ready;
}

static void qkx_workq_destroy_end(struct cam_req_mgr_core_workq *workq)
{
	struct qkx_workq_custody *owner;
	unsigned long flags;

	spin_lock_irqsave(&qkx_workq_lock, flags);
	owner = qkx_workq_find(workq);
	if (owner)
		list_del_init(&owner->entry);
	spin_unlock_irqrestore(&qkx_workq_lock, flags);
	if (owner) {
		kfree(owner->state);
		kfree(owner);
	}
}
#endif

int cam_req_mgr_workq_claim(struct cam_req_mgr_core_workq *workq,
	void (*idle)(void *), void *target)
{
#ifdef CONFIG_QKX_OWNER_GATE
	struct qkx_workq_custody *owner;
	unsigned long flags;

	if (!workq || !workq->task.num_task)
		return -EINVAL;
	owner = kzalloc(sizeof(*owner), GFP_KERNEL);
	if (!owner)
		return -ENOMEM;
	owner->state = kcalloc(workq->task.num_task,
		sizeof(*owner->state), GFP_KERNEL);
	if (!owner->state) {
		kfree(owner);
		return -ENOMEM;
	}
	owner->workq = workq;
	owner->idle = idle;
	owner->target = target;
	INIT_LIST_HEAD(&owner->entry);
	spin_lock_irqsave(&qkx_workq_lock, flags);
	if (qkx_workq_find(workq) ||
		atomic_read(&workq->task.free_cnt) != workq->task.num_task ||
		atomic_read(&workq->task.pending_cnt)) {
		spin_unlock_irqrestore(&qkx_workq_lock, flags);
		kfree(owner->state);
		kfree(owner);
		return -EBUSY;
	}
	list_add_tail(&owner->entry, &qkx_workq_owners);
	spin_unlock_irqrestore(&qkx_workq_lock, flags);
#endif
	return 0;
}

int cam_req_mgr_workq_close_owned(struct cam_req_mgr_core_workq *workq)
{
#ifdef CONFIG_QKX_OWNER_GATE
	struct qkx_workq_custody *owner;
	unsigned long flags;
	int result = 0;

	spin_lock_irqsave(&qkx_workq_lock, flags);
	owner = qkx_workq_find(workq);
	if (owner) {
		owner->closing = true;
		result = owner->error ? owner->error :
			(qkx_workq_idle(owner) ? 0 : -EBUSY);
	}
	spin_unlock_irqrestore(&qkx_workq_lock, flags);
	return result;
#else
	return 0;
#endif
}

int cam_req_mgr_workq_hold_owned(struct cam_req_mgr_core_workq *workq)
{
#ifdef CONFIG_QKX_OWNER_GATE
	struct qkx_workq_custody *owner;
	unsigned long flags;
	int result = -ENOENT;

	spin_lock_irqsave(&qkx_workq_lock, flags);
	owner = qkx_workq_find(workq);
	if (owner) {
		result = owner->error ? owner->error :
			(owner->closing || owner->retiring ? -ESHUTDOWN : 0);
		if (!result)
			owner->external++;
	}
	spin_unlock_irqrestore(&qkx_workq_lock, flags);
	return result;
#else
	return 0;
#endif
}

void cam_req_mgr_workq_put_owned(struct cam_req_mgr_core_workq *workq)
{
#ifdef CONFIG_QKX_OWNER_GATE
	struct qkx_workq_custody *owner;
	void (*idle)(void *) = NULL;
	void *target = NULL;
	unsigned long flags;

	spin_lock_irqsave(&qkx_workq_lock, flags);
	owner = qkx_workq_find(workq);
	if (owner) {
		if (!owner->external)
			owner->error = -EUCLEAN;
		else
			owner->external--;
		if (qkx_workq_idle(owner)) {
			idle = owner->idle;
			target = owner->target;
		}
	}
	spin_unlock_irqrestore(&qkx_workq_lock, flags);
	if (idle)
		idle(target);
#endif
}
