extern struct kmem_cache *g_cam_req_mgr_timer_cachep;

/* QKX_CAMERA_CUSTODY_TIMER_BEGIN */
#ifdef CONFIG_QKX_OWNER_GATE
struct qkx_timer_custody {
	struct cam_req_mgr_timer timer; /* Existing public layout stays unchanged. */
	struct list_head entry;
	struct cam_req_mgr_core_workq *workq;
	bool closing;
};
static LIST_HEAD(qkx_timer_owners);
static DEFINE_SPINLOCK(qkx_timer_lock);

static struct qkx_timer_custody *qkx_timer_find(struct cam_req_mgr_timer *timer)
{
	struct qkx_timer_custody *owner;

	list_for_each_entry(owner, &qkx_timer_owners, entry)
		if (&owner->timer == timer)
			return owner;
	return NULL;
}

static bool qkx_timer_rearm(struct cam_req_mgr_timer *timer,
	bool modify, int32_t expires)
{
	struct qkx_timer_custody *owner;
	unsigned long flags;
	bool found;

	spin_lock_irqsave(&qkx_timer_lock, flags);
	owner = qkx_timer_find(timer);
	found = owner != NULL;
	if (owner && !owner->closing) {
		if (modify)
			timer->expires = expires;
		mod_timer(&timer->sys_timer,
			jiffies + msecs_to_jiffies(timer->expires));
	}
	spin_unlock_irqrestore(&qkx_timer_lock, flags);
	return found;
}

static void qkx_timer_dispatch(struct timer_list *timer_data)
{
	struct cam_req_mgr_timer *timer = container_of(timer_data,
		struct cam_req_mgr_timer, sys_timer);
	struct qkx_timer_custody *owner;
	unsigned long flags;
	bool run;

	spin_lock_irqsave(&qkx_timer_lock, flags);
	owner = qkx_timer_find(timer);
	run = owner && !owner->closing;
	spin_unlock_irqrestore(&qkx_timer_lock, flags);
	/* Registration lease is held until del_timer_sync returns. */
	if (run)
		timer->timer_cb(timer_data);
}

static bool qkx_timer_owned(struct cam_req_mgr_timer *timer)
{
	unsigned long flags;
	bool owned;

	spin_lock_irqsave(&qkx_timer_lock, flags);
	owned = qkx_timer_find(timer) != NULL;
	spin_unlock_irqrestore(&qkx_timer_lock, flags);
	return owned;
}
#endif

int crm_timer_init_owned(struct cam_req_mgr_timer **timer,
	int32_t expires, void *parent, void (*timer_cb)(struct timer_list *),
	struct cam_req_mgr_core_workq *workq)
{
#ifdef CONFIG_QKX_OWNER_GATE
	struct qkx_timer_custody *owner;
	unsigned long flags;
	int result;

	if (!timer || *timer)
		return -EINVAL;
	result = cam_req_mgr_workq_hold_owned(workq);
	if (result)
		return result;
	owner = kzalloc(sizeof(*owner), GFP_KERNEL);
	if (!owner) {
		cam_req_mgr_workq_put_owned(workq);
		return -ENOMEM;
	}
	owner->workq = workq;
	owner->timer.expires = expires;
	owner->timer.parent = parent;
	owner->timer.timer_cb = timer_cb ? timer_cb : crm_timer_callback;
	INIT_LIST_HEAD(&owner->entry);
	timer_setup(&owner->timer.sys_timer, qkx_timer_dispatch, 0);
	spin_lock_irqsave(&qkx_timer_lock, flags);
	list_add_tail(&owner->entry, &qkx_timer_owners);
	*timer = &owner->timer;
	mod_timer(&owner->timer.sys_timer,
		jiffies + msecs_to_jiffies(expires));
	spin_unlock_irqrestore(&qkx_timer_lock, flags);
	return 0;
#else
	return crm_timer_init(timer, expires, parent, timer_cb);
#endif
}

int crm_timer_close_owned(struct cam_req_mgr_timer **timer)
{
#ifdef CONFIG_QKX_OWNER_GATE
	struct qkx_timer_custody *owner;
	struct cam_req_mgr_core_workq *workq;
	unsigned long flags;

	if (!timer || !*timer)
		return 0;
	if (in_interrupt())
		return -EWOULDBLOCK;
	spin_lock_irqsave(&qkx_timer_lock, flags);
	owner = qkx_timer_find(*timer);
	if (!owner) {
		spin_unlock_irqrestore(&qkx_timer_lock, flags);
		crm_timer_exit(timer);
		return 0;
	}
	if (owner->closing) {
		spin_unlock_irqrestore(&qkx_timer_lock, flags);
		return -EBUSY;
	}
	owner->closing = true;
	spin_unlock_irqrestore(&qkx_timer_lock, flags);
	del_timer_sync(&owner->timer.sys_timer);
	spin_lock_irqsave(&qkx_timer_lock, flags);
	list_del_init(&owner->entry);
	*timer = NULL;
	workq = owner->workq;
	spin_unlock_irqrestore(&qkx_timer_lock, flags);
	/* Never notify the owning driver while holding the timer lock. */
	cam_req_mgr_workq_put_owned(workq);
	kfree(owner);
	return 0;
#else
	crm_timer_exit(timer);
	return 0;
#endif
}
/* QKX_CAMERA_CUSTODY_TIMER_END */

