static struct cam_req_mgr_core_link g_links[MAXIMUM_LINKS_PER_SESSION];

/* QKX_CAMERA_CUSTODY_CORE_BEGIN */
#ifdef CONFIG_QKX_OWNER_GATE
struct qkx_link_custody {
	int handle;
	unsigned int users;
	unsigned long generation;
	bool live, closing;
	int pending; /* 1 unlink, 2 session destruction */
	int error;
};
static struct qkx_link_custody qkx_links[MAXIMUM_LINKS_PER_SESSION];
static DEFINE_SPINLOCK(qkx_link_lock);
static bool qkx_root_closing;

/* Session topology and sidecars are serialized by crm_lock. */
struct qkx_session_custody {
	struct list_head entry;
	struct cam_req_mgr_core_session *session;
	int handle;
	unsigned long generation;
	bool closing, pending, is_shutdown;
	int error;
};
static LIST_HEAD(qkx_sessions);
/* Never reset across reprobe: a delayed retry must not match a new session. */
static unsigned long qkx_session_generation;

static struct qkx_session_custody *qkx_session_find(
	struct cam_req_mgr_core_session *session)
{
	struct qkx_session_custody *owner;

	if (!session)
		return NULL;
	list_for_each_entry(owner, &qkx_sessions, entry)
		if (owner->session == session &&
			owner->handle == session->session_hdl)
			return owner;
	return NULL;
}

static int qkx_session_prepare(struct cam_req_mgr_core_session *session,
	struct qkx_session_custody **prepared)
{
	struct qkx_session_custody *owner;

	if (qkx_session_generation == (unsigned long)-1)
		return -EOVERFLOW;
	owner = kzalloc(sizeof(*owner), GFP_KERNEL);
	if (!owner)
		return -ENOMEM;
	owner->session = session;
	owner->generation = ++qkx_session_generation;
	INIT_LIST_HEAD(&owner->entry);
	*prepared = owner;
	return 0;
}

static void qkx_session_publish(struct qkx_session_custody *owner, int handle)
{
	owner->handle = handle;
	list_add_tail(&owner->entry, &qkx_sessions);
}

static int qkx_session_admit(struct cam_req_mgr_core_session *session)
{
	struct qkx_session_custody *owner = qkx_session_find(session);

	if (!owner)
		return -EUCLEAN;
	return owner->closing || owner->error ? -ESHUTDOWN : 0;
}


static struct qkx_link_custody *qkx_link_owner(
	struct cam_req_mgr_core_link *link)
{
	int i;

	for (i = 0; i < MAXIMUM_LINKS_PER_SESSION; i++)
		if (&g_links[i] == link)
			return &qkx_links[i];
	return NULL;
}

static void qkx_link_publish(struct cam_req_mgr_core_link *link)
{
	struct qkx_link_custody *owner;
	unsigned long flags;

	spin_lock_irqsave(&qkx_link_lock, flags);
	owner = qkx_link_owner(link);
	if (owner) {
		owner->handle = link->link_hdl;
		owner->users = 0;
		owner->generation++;
		owner->closing = false;
		owner->pending = 0;
		owner->error = 0;
		owner->live = true;
	}
	spin_unlock_irqrestore(&qkx_link_lock, flags);
}

static struct cam_req_mgr_core_link *qkx_link_get(int handle)
{
	struct cam_req_mgr_core_link *link = NULL;
	unsigned long flags;
	int i;

	/* Lookup and lease are one operation; never pin a returned raw handle. */
	spin_lock_irqsave(&qkx_link_lock, flags);
	for (i = 0; i < MAXIMUM_LINKS_PER_SESSION; i++)
		if (qkx_links[i].live && !qkx_links[i].closing &&
			!qkx_links[i].error &&
			qkx_links[i].handle == handle) {
			qkx_links[i].users++;
			link = &g_links[i];
			break;
		}
	spin_unlock_irqrestore(&qkx_link_lock, flags);
	return link;
}

static bool qkx_link_accepts_control(struct cam_req_mgr_core_link *link)
{
	struct qkx_link_custody *owner;
	unsigned long flags;
	bool ready;

	spin_lock_irqsave(&qkx_link_lock, flags);
	owner = qkx_link_owner(link);
	ready = owner && owner->live && !owner->closing && !owner->error;
	spin_unlock_irqrestore(&qkx_link_lock, flags);
	return ready;
}

static void qkx_link_put(struct cam_req_mgr_core_link *link)
{
	struct qkx_link_custody *owner;
	unsigned long flags;
	bool wake = false;

	if (!link)
		return;
	spin_lock_irqsave(&qkx_link_lock, flags);
	owner = qkx_link_owner(link);
	if (owner) {
		if (!owner->users)
			owner->error = -EUCLEAN;
		else
			owner->users--;
		wake = owner->closing && !owner->users && owner->pending;
	}
	spin_unlock_irqrestore(&qkx_link_lock, flags);
	if (wake)
		cam_req_mgr_custody_wake();
}

static int qkx_link_close(struct cam_req_mgr_core_link *link)
{
	struct qkx_link_custody *owner;
	unsigned long flags;
	int result = 0;

	spin_lock_irqsave(&qkx_link_lock, flags);
	owner = qkx_link_owner(link);
	if (!owner || !owner->live) {
		result = -EUCLEAN;
	} else {
		owner->closing = true;
		result = owner->error ? owner->error :
			(owner->users ? -EBUSY : 0);
	}
	spin_unlock_irqrestore(&qkx_link_lock, flags);
	return result;
}

static void qkx_link_pending(struct cam_req_mgr_core_link *link,
	int operation, int error)
{
	struct qkx_link_custody *owner;
	unsigned long flags;
	bool wake = false;

	spin_lock_irqsave(&qkx_link_lock, flags);
	owner = qkx_link_owner(link);
	if (owner) {
		bool changed = operation > owner->pending;

		if (changed)
			owner->pending = operation;
		/* Only temporary in-flight custody is automatically retried. */
		if (error && error != -EBUSY && !owner->error)
			owner->error = error;
		wake = changed && !owner->users && !owner->error;
	}
	spin_unlock_irqrestore(&qkx_link_lock, flags);
	if (wake)
		cam_req_mgr_custody_wake();
}

static int qkx_link_fail(struct cam_req_mgr_core_link *link, int error)
{
	struct qkx_link_custody *owner;
	unsigned long flags;

	spin_lock_irqsave(&qkx_link_lock, flags);
	owner = qkx_link_owner(link);
	if (owner && !owner->error)
		owner->error = error;
	spin_unlock_irqrestore(&qkx_link_lock, flags);
	return error;
}

static void qkx_link_retire(struct cam_req_mgr_core_link *link)
{
	struct qkx_link_custody *owner;
	unsigned long flags;

	spin_lock_irqsave(&qkx_link_lock, flags);
	owner = qkx_link_owner(link);
	if (owner) {
		owner->live = false;
		owner->pending = 0;
	}
	spin_unlock_irqrestore(&qkx_link_lock, flags);
}

static void qkx_link_idle(void *target)
{
	cam_req_mgr_custody_wake();
}

static int __cam_req_mgr_unlink(struct cam_req_mgr_core_link *link);
static void __cam_req_mgr_unreserve_link(
	struct cam_req_mgr_core_session *session,
	struct cam_req_mgr_core_link *link);

static int qkx_session_destroy(struct cam_req_mgr_session_info *ses_info,
	bool is_shutdown, unsigned long expected_generation)
{
	struct cam_req_mgr_core_session *session;
	struct cam_req_mgr_core_link *link;
	struct qkx_session_custody *owner;
	int i, result = 0, first = 0;

	if (!ses_info)
		return -EINVAL;
	mutex_lock(&g_crm_core_dev->crm_lock);
	session = cam_get_session_priv(ses_info->session_hdl);
	if (!session || session->session_hdl != ses_info->session_hdl) {
		result = -ENOENT;
		goto custody_end;
	}
	owner = qkx_session_find(session);
	if (!owner) {
		result = -EUCLEAN;
		goto custody_end;
	}
	if (expected_generation && owner->generation != expected_generation) {
		result = -ENOENT;
		goto custody_end;
	}
	/* Intent belongs to the session, not to whichever child still exists. */
	owner->closing = true;
	owner->pending = true;
	owner->is_shutdown |= is_shutdown;
	if (owner->error) {
		result = owner->error;
		goto custody_end;
	}
	for (i = 0; i < MAXIMUM_LINKS_PER_SESSION; i++) {
		link = session->links[i];
		if (!link)
			continue;
		link->is_shutdown = owner->is_shutdown;
		qkx_link_pending(link, 2, 0);
		result = __cam_req_mgr_unlink(link);
		if (result) {
			qkx_link_pending(link, 2, result);
			if (result != -EBUSY && !owner->error)
				owner->error = result;
			if (!first)
				first = result;
			continue;
		}
		__cam_req_mgr_unreserve_link(session, link);
	}
	if (first) {
		result = first;
		goto custody_end;
	}
	result = cam_destroy_session_hdl(ses_info->session_hdl);
	if (result) {
		/* A failed final handle operation is never replayed automatically. */
		owner->error = result;
		goto custody_end;
	}
	list_del(&session->entry);
	list_del(&owner->entry);
	mutex_destroy(&session->lock);
	kfree(session);
	kfree(owner);
custody_end:
	mutex_unlock(&g_crm_core_dev->crm_lock);
	return result;
}

