void cam_req_mgr_custody_retry(void)
{
#ifdef CONFIG_QKX_OWNER_GATE
	struct {
		int handle;
		unsigned long generation;
	} pending[CAM_REQ_MGR_MAX_SESSION_HANDLES];
	struct qkx_session_custody *owner;
	struct cam_req_mgr_session_info session;
	struct cam_req_mgr_unlink_info unlink;
	unsigned long flags;
	int i, count = 0, operation;

	if (!g_crm_core_dev)
		return;
	mutex_lock(&g_crm_core_dev->crm_lock);
	list_for_each_entry(owner, &qkx_sessions, entry) {
		if (!owner->closing || !owner->pending || owner->error)
			continue;
		if (qkx_session_find(owner->session) != owner) {
			owner->error = -EUCLEAN;
			continue;
		}
		if (count >= CAM_REQ_MGR_MAX_SESSION_HANDLES) {
			owner->error = -EOVERFLOW;
			continue;
		}
		pending[count].handle = owner->handle;
		pending[count++].generation = owner->generation;
	}
	mutex_unlock(&g_crm_core_dev->crm_lock);
	/* One bounded pass. Validate the generation again after reacquiring lock. */
	for (i = 0; i < count; i++) {
		session.session_hdl = pending[i].handle;
		qkx_session_destroy(&session, false, pending[i].generation);
	}
	for (i = 0; i < MAXIMUM_LINKS_PER_SESSION; i++) {
		mutex_lock(&g_crm_core_dev->crm_lock);
		spin_lock_irqsave(&qkx_link_lock, flags);
		operation = qkx_links[i].live && !qkx_links[i].error &&
			qkx_links[i].pending == 1;
		if (operation) {
			owner = qkx_session_find(g_links[i].parent);
			if (!owner) {
				qkx_links[i].error = -EUCLEAN;
				operation = 0;
			} else {
				unlink.session_hdl = owner->handle;
				unlink.link_hdl = qkx_links[i].handle;
			}
		}
		spin_unlock_irqrestore(&qkx_link_lock, flags);
		mutex_unlock(&g_crm_core_dev->crm_lock);
		if (operation)
			cam_req_mgr_unlink(&unlink);
	}
#endif
}

int cam_req_mgr_custody_shutdown(void)
{
#ifdef CONFIG_QKX_OWNER_GATE
	struct cam_req_mgr_core_session *session;
	struct cam_req_mgr_session_info info;
	int result;

	if (!g_crm_core_dev)
		return -EINVAL;
	mutex_lock(&g_crm_core_dev->crm_lock);
	qkx_root_closing = true;
	mutex_unlock(&g_crm_core_dev->crm_lock);
	for (;;) {
		mutex_lock(&g_crm_core_dev->crm_lock);
		if (list_empty(&g_crm_core_dev->session_head)) {
			mutex_unlock(&g_crm_core_dev->crm_lock);
			return 0;
		}
		session = list_first_entry(&g_crm_core_dev->session_head,
			struct cam_req_mgr_core_session, entry);
		info.session_hdl = session->session_hdl;
		mutex_unlock(&g_crm_core_dev->crm_lock);
		result = cam_req_mgr_destroy_session(&info, true);
		if (result)
			return result;
	}
#else
	cam_req_mgr_handle_core_shutdown();
	return 0;
#endif
}

int cam_req_mgr_custody_reopen(void)
{
#ifdef CONFIG_QKX_OWNER_GATE
