/* QKX_CAMERA_CUSTODY_DEV_BEGIN */
#ifdef CONFIG_QKX_OWNER_GATE
static DEFINE_SPINLOCK(qkx_finalize_lock);
static bool qkx_finalize_running, qkx_finalize_dirty;
static bool qkx_finalize_stopping;
static bool qkx_close_pending;
static struct v4l2_fh *qkx_close_fh;
static void qkx_finalize_work(struct work_struct *work);
static DECLARE_WORK(qkx_finalize_job, qkx_finalize_work);

void cam_req_mgr_custody_wake(void)
{
	unsigned long flags;

	spin_lock_irqsave(&qkx_finalize_lock, flags);
	if (qkx_finalize_stopping) {
		spin_unlock_irqrestore(&qkx_finalize_lock, flags);
		return;
	}
	qkx_finalize_dirty = true;
	if (!qkx_finalize_running) {
		qkx_finalize_running = true;
		/* Publish under the same lock used to stop notifier admission. */
		schedule_work(&qkx_finalize_job);
	}
	spin_unlock_irqrestore(&qkx_finalize_lock, flags);
}

/* Called with the root close locks held, on a distinct system worker. */
static int qkx_finish_close(void)
{
	struct v4l2_subdev *sd;
	struct v4l2_subdev_fh *subdev_fh;
	int result;

	result = cam_req_mgr_custody_shutdown();
	if (result)
		return result;
	subdev_fh = to_v4l2_subdev_fh(qkx_close_fh);
	list_for_each_entry(sd, &g_dev.v4l2_dev->subdevs, list) {
		if (!(sd->flags & V4L2_SUBDEV_FL_HAS_DEVNODE))
			continue;
		if (sd->internal_ops && sd->internal_ops->close)
			sd->internal_ops->close(sd, subdev_fh);
	}
	/* The detached V4L2 allocation, never the dying struct file, is held. */
	if (qkx_close_fh) {
		v4l2_fh_del(qkx_close_fh);
		v4l2_fh_exit(qkx_close_fh);
		kfree(qkx_close_fh);
		qkx_close_fh = NULL;
	}
	cam_req_mgr_util_free_hdls();
	cam_mem_mgr_deinit();
	qkx_close_pending = false;
	return 0;
}

static void qkx_finalize_work(struct work_struct *work)
{
	unsigned long flags;

	for (;;) {
		spin_lock_irqsave(&qkx_finalize_lock, flags);
		if (!qkx_finalize_dirty) {
			qkx_finalize_running = false;
			spin_unlock_irqrestore(&qkx_finalize_lock, flags);
			return;
		}
		qkx_finalize_dirty = false;
		spin_unlock_irqrestore(&qkx_finalize_lock, flags);
		cam_req_mgr_rwsem_write_op(CAM_SUBDEV_LOCK);
		mutex_lock(&g_dev.cam_lock);
		cam_req_mgr_custody_retry();
		if (qkx_close_pending)
			qkx_finish_close();
		mutex_unlock(&g_dev.cam_lock);
		cam_req_mgr_rwsem_write_op(CAM_SUBDEV_UNLOCK);
	}
}
